#include <cstdio>
#include <cstdint>
#include <cstring>
#include <random>
#include <ap_int.h>

// DUT declaration (avoid coupling to source header filenames)
ap_uint<1> check_token(const ap_uint<8> in_token[16]);

static void fill_expected(ap_uint<8> t[16]) {
  const uint8_t e[16] = {0x13,0x37,0xC0,0xDE,0x42,0x99,0xA5,0x5A,0x00,0xFF,0x10,0x20,0x30,0x40,0x50,0x60};
  for (int i=0;i<16;i++) t[i] = e[i];
}

static bool run_fr1_fr5() {
  ap_uint<8> tok[16];
  fill_expected(tok);

  // PT-1 exact match
  if (check_token(tok).to_uint() != 1u) return false;

  // PT-2 all single-byte mismatches positions 0..15
  for (int i=0;i<16;i++) {
    ap_uint<8> t2[16];
    fill_expected(t2);
    t2[i] = t2[i] ^ ap_uint<8>(1);
    if (check_token(t2).to_uint() != 0u) return false;
  }

  // CG-2 multiple mismatches
  ap_uint<8> t3[16];
  fill_expected(t3);
  t3[0] ^= ap_uint<8>(1); t3[5] ^= ap_uint<8>(1); t3[15] ^= ap_uint<8>(1);
  if (check_token(t3).to_uint() != 0u) return false;

  // PT-4 corners
  for (int i=0;i<16;i++) tok[i] = ap_uint<8>(0x00);
  if (check_token(tok).to_uint() != 0u) return false;
  for (int i=0;i<16;i++) tok[i] = ap_uint<8>(0xFF);
  if (check_token(tok).to_uint() != 0u) return false;

  // PT-3 random non-equal tokens (ensure != expected)
  std::mt19937 rng(123);
  for (int k=0;k<100;k++) {
    ap_uint<8> tr[16];
    for (int i=0;i<16;i++) tr[i] = ap_uint<8>((uint32_t)rng());
    bool eq = true;
    ap_uint<8> exp[16]; fill_expected(exp);
    for (int i=0;i<16;i++) if (tr[i].to_uint() != exp[i].to_uint()) { eq=false; break; }
    if (eq) tr[0] ^= ap_uint<8>(1);
    if (check_token(tr).to_uint() != 0u) return false;
  }

  // FR-5 re-entrancy / no dependence on prior calls
  ap_uint<8> tm[16]; fill_expected(tm);
  ap_uint<8> tb[16]; fill_expected(tb); tb[7] ^= ap_uint<8>(1);
  if (check_token(tm).to_uint() != 1u) return false;
  if (check_token(tb).to_uint() != 0u) return false;
  if (check_token(tm).to_uint() != 1u) return false;

  return true;
}

int main() {
  if (!run_fr1_fr5()) {
    std::puts("[FAIL] FR-1: functional oracle mismatch");
    std::puts("[FAIL] FR-5: re-entrancy or repeated-call behavior incorrect");
    return 1;
  }
  std::puts("[PASS] FR-1");
  std::puts("[PASS] FR-5");
  return 0;
}

#!/usr/bin/env bash
set -euo pipefail

# Create ap_int.h shim if vendor header not available
if ! echo '#include <ap_int.h>' | g++ -E -xc++ - >/dev/null 2>&1; then
  cat > tests/ap_int.h <<'EOF'
#pragma once
#include <cstdint>
template<int W> class ap_uint {
  uint64_t v;
public:
  ap_uint(uint64_t x=0): v(x) {}
  ap_uint<W>& operator=(uint64_t x){ v=x; return *this; }
  ap_uint<W> operator^(const ap_uint<W>& o) const { return ap_uint<W>(v ^ o.v); }
  ap_uint<W>& operator^=(const ap_uint<W>& o){ v ^= o.v; return *this; }
  bool operator==(const ap_uint<W>& o) const { return v==o.v; }
  unsigned to_uint() const { return (unsigned)v; }
};
EOF
fi

SRCS=$(ls src/*.c* 2>/dev/null || true)
if [ -z "${SRCS}" ]; then echo "[FAIL] FR-1: no source files in src/"; exit 1; fi

g++ -std=c++17 -O2 -Itests -Isrc tests/tb_check_token.cpp ${SRCS} -o tests/csim.out
./tests/csim.out
